// 日本語の表記揺れ吸収：全角半角・大小・カタカナ/ひらがなを統一して検索用の共通形にする
function normJa(s) {
  if (s == null) return "";
  return String(s).normalize("NFKC") // 全角→半角・互換文字を標準化
  .toLowerCase().replace(/[\u30a1-\u30f6]/g, c => String.fromCharCode(c.charCodeAt(0) - 0x60)); // カタカナ→ひらがな
}
