  // KMeansのサンプリング間隔（px）
  KMEANS_K: 8,
  KMEANS_ITER: 10,
  COLOR_MIN_SHARE: 0.05,
  EDGE_MAG: 60,
  // エッジ判定のしきい値
  MARGIN_BAND: 0.08,
